// Part 5D: the native git guard. A Bash command that would commit, merge,
// cherry-pick, rebase or push while the repo it runs in is on a guarded branch
// (main, master by default) is denied; so is a push that NAMES a guarded
// branch (`push origin main`, `HEAD:main`), from any branch. A push on a
// guarded branch is a push OF it only when its refspecs are empty, `--all`,
// `--mirror`, `HEAD`, or the branch itself; a tag, `--tags`, another branch
// or a delete of one passes. It replaces the
// chassis's pre-git-guard.sh. Pure: no `$`.
//
// It reads the command the way a shell does, not as text: quotes keep their
// words whole, heredoc bodies are skipped, and only the FIRST command word of
// each pipeline segment (after `VAR=x` assignments) can be `git`; so a file
// being written that merely contains "git commit" never trips it. It follows
// a command-position `cd <dir>` (scoped to its subshell) and git's own `-C`.
// A branch made in the same command (`checkout -b feat && commit`) is off the
// guard; a bare checkout re-arms it, and a checkout of a guarded branch is
// that branch. An accident tripwire, not adversary-proof: `bash -c "…"`,
// `eval` and the like are not looked into.

export const WRITE_VERBS = ['commit', 'merge', 'cherry-pick', 'rebase', 'push'] as const
export const DEFAULT_GUARD_BRANCHES = ['main', 'master'] as const

export type BranchState = { kind: 'unknown' } | { kind: 'off' } | { kind: 'on'; branch: string }
export type GitWrite = {
  verb: string
  /** The folder it runs in, from `cd` and `-C`, relative or absolute; '' is the command's own folder. */
  dir: string
  /** What the command itself did to the branch before this write. */
  state: BranchState
  /** A push refspec naming a guarded branch. */
  namesGuarded?: string
  /**
   * A push only: the source of each refspec (`HEAD`, a branch, a tag), with a
   * delete or `--tags` contributing none. Absent when the push is of the
   * current branch whatever they are (no refspecs, `--all`, `--mirror`).
   */
  pushSrcs?: string[]
}

export const parseGuardBranches = (s: string | undefined): string[] => {
  const list = (s ?? '').split(',').map(x => x.trim()).filter(Boolean)
  return list.length > 0 ? list : [...DEFAULT_GUARD_BRANCHES]
}

/** `dir` read against `cwd`: absolute wins, `.` and `..` folded. */
export function joinDir(cwd: string, dir: string): string {
  if (!dir) return cwd
  const raw = dir.startsWith('/') ? dir : `${cwd.replace(/\/+$/, '')}/${dir}`
  const out: string[] = []
  for (const part of raw.split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') out.pop()
    else out.push(part)
  }
  return `/${out.join('/')}`
}

const SEPS = ['&&', '||', ';;', ';', '|&', '|', '&', '(', ')', '\n', '$(', '`']

type Tok = { t: string; sep: boolean }

/**
 * Shell-like tokens: quotes and backslashes honoured, `;` `&&` `||` `|` `&`
 * `(` `)` `$(` and newlines as separator tokens, comments dropped, heredoc
 * bodies (`<<EOF` … `EOF`, `<<-` with leading tabs) skipped.
 */
function lex(text: string): Tok[] {
  const toks: Tok[] = []
  let word = ''
  let inWord = false
  const pendingDocs: { delim: string; dash: boolean }[] = []
  const flush = () => {
    if (inWord) toks.push({ t: word, sep: false })
    word = ''
    inWord = false
  }
  let i = 0
  const n = text.length
  while (i < n) {
    const c = text[i] as string
    if (c === '\\' && i + 1 < n) {
      if (text[i + 1] === '\n') i += 2
      else {
        word += text[i + 1]
        inWord = true
        i += 2
      }
      continue
    }
    if (c === "'") {
      const end = text.indexOf("'", i + 1)
      word += end < 0 ? text.slice(i + 1) : text.slice(i + 1, end)
      inWord = true
      i = end < 0 ? n : end + 1
      continue
    }
    if (c === '"') {
      let j = i + 1
      while (j < n && text[j] !== '"') {
        if (text[j] === '\\' && j + 1 < n) {
          word += text[j + 1]
          j += 2
        } else {
          word += text[j]
          j += 1
        }
      }
      inWord = true
      i = j + 1
      continue
    }
    if (c === '#' && !inWord) {
      while (i < n && text[i] !== '\n') i += 1
      continue
    }
    if (c === '<' && text.startsWith('<<', i) && !text.startsWith('<<<', i)) {
      flush()
      let j = i + 2
      const dash = text[j] === '-'
      if (dash) j += 1
      while (j < n && (text[j] === ' ' || text[j] === '\t')) j += 1
      let delim = ''
      while (j < n && !/[\s;&|()<>]/.test(text[j] as string)) {
        const d = text[j] as string
        if (d !== "'" && d !== '"' && d !== '\\') delim += d
        j += 1
      }
      if (delim) pendingDocs.push({ delim, dash })
      i = j
      continue
    }
    if (c === '\n') {
      flush()
      toks.push({ t: '\n', sep: true })
      i += 1
      // skip each pending heredoc body, in order, through its delimiter line
      while (pendingDocs.length > 0 && i <= n) {
        const doc = pendingDocs.shift() as { delim: string; dash: boolean }
        for (;;) {
          if (i >= n) break
          const end = text.indexOf('\n', i)
          const line = end < 0 ? text.slice(i) : text.slice(i, end)
          i = end < 0 ? n : end + 1
          if ((doc.dash ? line.replace(/^\t+/, '') : line) === doc.delim) break
        }
      }
      continue
    }
    if (c === ' ' || c === '\t' || c === '\r') {
      flush()
      i += 1
      continue
    }
    const sep = SEPS.find(s => s !== '\n' && text.startsWith(s, i))
    if (sep) {
      flush()
      toks.push({ t: sep, sep: true })
      i += sep.length
      continue
    }
    if (c === '>' || c === '<') {
      flush()
      i += text[i + 1] === c ? 2 : 1
      continue
    }
    word += c
    inWord = true
    i += 1
  }
  flush()
  return toks
}

/** The words and separators of a command, as the guard reads them. */
export const tokenize = (text: string): string[] => lex(text).map(t => t.t)

const OPT_ARG = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace', '--exec-path', '--config-env', '--super-prefix', '--attr-source'])
const CREATE = new Set(['-b', '-B', '-c', '-C', '--create', '--force-create', '--orphan'])
const ABORTS = new Set(['--abort', '--quit', '--skip'])
const PUSH_OPT_ARG = new Set(['-o', '--push-option', '--repo', '--receive-pack', '--exec'])
const ASSIGN = /^[A-Za-z_][A-Za-z0-9_]*=/
const PREFIXES = new Set(['command', 'time', 'nohup', 'env'])

const firstRef = (rest: readonly string[]): string | undefined => rest.find(t => !t.startsWith('-'))

const bare = (ref: string): string => ref.replace(/^\+/, '').replace(/^refs\/heads\//, '')

/** What a push's words say: the guarded branch it names as a destination, and the sources it pushes (undefined: the current branch, whatever they are). */
function pushInfo(rest: readonly string[], guarded: readonly string[]): { named?: string; srcs?: string[] } {
  const words: string[] = []
  let del = false
  let tags = false
  for (let i = 0; i < rest.length; i += 1) {
    const w = rest[i] as string
    if (PUSH_OPT_ARG.has(w)) {
      i += 1
      continue
    }
    if (w === '--all' || w === '--mirror') return { named: guarded[0] }
    if (w === '--delete' || w === '-d') del = true
    else if (w === '--tags') tags = true
    if (!w.startsWith('-')) words.push(w)
  }
  const specs = words.slice(1)
  let named: string | undefined
  const srcs: string[] = []
  for (const spec of specs) {
    const colon = spec.lastIndexOf(':')
    const dst = bare(colon >= 0 ? spec.slice(colon + 1) : spec)
    if (named === undefined && guarded.includes(dst)) named = dst
    const src = colon >= 0 ? spec.slice(0, colon) : del ? '' : spec
    if (src) srcs.push(bare(src))
  }
  const current = specs.length === 0 && !tags
  return { ...(named ? { named } : {}), ...(current ? {} : { srcs }) }
}

/** Every git write in a Bash command, in order, with its folder and what the command did to the branch first. */
export function gitWrites(command: string, guarded: readonly string[]): GitWrite[] {
  const toks = lex(command)
  const writes: GitWrite[] = []
  let state: BranchState = { kind: 'unknown' }
  let cwd = ''
  const stack: string[] = []
  let i = 0
  while (i < toks.length) {
    const tok = toks[i] as Tok
    if (tok.sep) {
      if (tok.t === '(' || tok.t === '$(') stack.push(cwd)
      else if (tok.t === ')' && stack.length > 0) cwd = stack.pop() as string
      i += 1
      continue
    }
    // one segment: the words up to the next separator
    let end = i
    while (end < toks.length && !(toks[end] as Tok).sep) end += 1
    const words = toks.slice(i, end).map(t => t.t)
    i = end
    let k = 0
    while (k < words.length && (ASSIGN.test(words[k] as string) || PREFIXES.has(words[k] as string))) k += 1
    const head = words[k]
    if (head === undefined) continue
    if (head === 'cd') {
      const target = words.slice(k + 1).find(w => !w.startsWith('-'))
      // kept relative until the hook reads it against the command's own folder (joinDir)
      if (target !== undefined) cwd = target.startsWith('/') || !cwd ? target : `${cwd}/${target}`
      continue
    }
    if (head !== 'git' && !head.endsWith('/git')) continue
    let j = k + 1
    let cdir = ''
    while (j < words.length) {
      const o = words[j] as string
      if (o === '-C' && j + 1 < words.length) {
        const next = words[j + 1] as string
        cdir = cdir && !next.startsWith('/') ? `${cdir}/${next}` : next
        j += 2
      } else if (OPT_ARG.has(o)) j += 2
      else if (o.startsWith('-')) j += 1
      else break
    }
    const sub = words[j]
    const rest = words.slice(j + 1)
    const dir = cdir ? (cwd && !cdir.startsWith('/') ? `${cwd}/${cdir}` : cdir) : cwd
    if (sub === 'checkout' || sub === 'switch') {
      if (rest.includes('--')) continue
      if (rest.some(f => CREATE.has(f))) {
        const ref = firstRef(rest)
        state = ref === undefined ? { kind: 'unknown' } : guarded.includes(ref) ? { kind: 'on', branch: ref } : { kind: 'off' }
      } else {
        const ref = firstRef(rest)
        state = ref !== undefined && guarded.includes(ref) ? { kind: 'on', branch: ref } : { kind: 'unknown' }
      }
      continue
    }
    if (sub === undefined || !(WRITE_VERBS as readonly string[]).includes(sub)) continue
    if (sub !== 'commit' && sub !== 'push' && rest.some(f => ABORTS.has(f))) continue
    const push = sub === 'push' ? pushInfo(rest, guarded) : {}
    writes.push({ verb: sub, dir, state, ...(push.named ? { namesGuarded: push.named } : {}), ...(push.srcs ? { pushSrcs: push.srcs } : {}) })
  }
  return writes
}

/** The deny for one write, given the branch its folder is on now (undefined when unknown). */
export function guardDeny(w: GitWrite, currentBranch: string | undefined, guarded: readonly string[]): string | undefined {
  const deny = (branch: string) => `chassis-delegation: no ${w.verb} on ${branch}; branch first (git checkout -b agent/<domain>/<id>)`
  if (w.namesGuarded) return deny(w.namesGuarded)
  if (w.pushSrcs) {
    // a push of other refs (a tag, another branch, a delete) is not a push of the current branch
    const here = w.state.kind === 'on' ? w.state.branch : currentBranch
    if (!w.pushSrcs.some(src => src === 'HEAD' || src === here)) return undefined
  }
  if (w.state.kind === 'off') return undefined
  if (w.state.kind === 'on') return deny(w.state.branch)
  return currentBranch !== undefined && guarded.includes(currentBranch) ? deny(currentBranch) : undefined
}

files.hooks/lib/handback.ts:
// GH-2 (GH-2): where a worker's hand-back reaches the mod.
//
// A worker that ends its run with SubagentHandback leaves its report in that
// call's `message`, not in its turn's answer. Foreground, the Agent result
// carries it (`handbackReport.text`). Background, `turn.complete` carries the
// answer alone, and a `tool.call` hook for SubagentHandback (a tool the
// engine's tool list does not name) saw nothing in the live runs of GH-2.
// The call sits in the worker's own transcript, which
// `$.session.messages({ agentId })` reads. Pure: the caller reads the
// transcript and hands the rows in.

export const HANDBACK_TOOL = 'SubagentHandback'

/** One transcript row, as `$.session.messages({ agentId })` gives it: the fields read here. */
export type TranscriptRow = {
  role?: unknown
  text?: unknown
  toolUses?: unknown
  toolResults?: unknown
}

type ToolUse = { tool?: unknown; input?: unknown; isError?: unknown }

const isPrompt = (r: TranscriptRow) => r.role === 'user' && !(Array.isArray(r.toolResults) && r.toolResults.length > 0)

/**
 * The hand-back messages of the run the transcript ends on, in order: each
 * SubagentHandback call's `message` after the run's prompt (the last user row
 * that carries no tool results: the brief, or a resume). An earlier run's
 * hand-back is never read again, and a call that errored (refused, withheld)
 * delivered nothing, so it is left out.
 */
export function handbackMessages(rows: readonly TranscriptRow[]): string[] {
  let start = 0
  rows.forEach((r, i) => {
    if (isPrompt(r)) start = i + 1
  })
  const out: string[] = []
  for (const r of rows.slice(start)) {
    if (r.role !== 'assistant' || !Array.isArray(r.toolUses)) continue
    for (const use of r.toolUses as ToolUse[]) {
      if (use?.tool !== HANDBACK_TOOL || use.isError === true) continue
      const message = (use.input as { message?: unknown } | undefined)?.message
      if (typeof message === 'string' && message.trim() !== '') out.push(message)
    }
  }
  return out
}

/**
 * Everything a worker said at the end of its run, in the order it said it:
 * the turn's answer, then each hand-back (the SubagentHandback call ends the
 * run, so a delivered one is its last word). `extractReport` takes the last
 * `[[report]]` of it, so the last report wins across answer and hand-back. A
 * text met twice (one hand-back seen by two routes) is kept once.
 */
export function workerSaid(answer: string, handbacks: readonly string[]): string {
  const seen = new Set<string>()
  const parts: string[] = []
  for (const p of [answer, ...handbacks]) {
    if (!p || seen.has(p)) continue
    seen.add(p)
    parts.push(p)
  }
  return parts.join('\n')
}

files.hooks/lib/norepo.ts:
// Part 3A: a task with no git repo. A brief whose header says `repo=none`, or
// names a folder that is not a git work tree, has no branch, sha or diff for
// the native verifier (./verify-native.ts) to read. The mod checks three things only:
// every `files=` path of the report exists under the brief's first scope
// root; no such path lies outside the scope (or inside a forbid); and the
// gate exits 0. The gate resolves as for any brief (./gates.ts
// resolveGateRuns): the gate map's command for the header's `gate=` id, or the
// `gate=` itself when it is a bare command the allowlist takes (`claude plugin
// validate <absolute folder>`). Pure: no `$`, no imports.

/** `git -C <dir> rev-parse --is-inside-work-tree`: on the allowlist (rev-parse). */
export const workTreeArgv = (dir: string): string[] => ['git', '-C', dir, 'rev-parse', '--is-inside-work-tree']

/** A folder git does not know (exit ≠ 0), or the inside of a .git folder (`false`). */
export const isNotWorkTree = (r: { exitCode: number; stdout: string }): boolean => r.exitCode !== 0 || r.stdout.trim() === 'false'

const GLOB_CHARS = /[*?[{]/

/** The folder before a glob's first glob character; a path with none is its own root. */
export function globRoot(glob: string): string {
  const at = glob.search(GLOB_CHARS)
  if (at < 0) return glob.replace(/\/+$/, '') || '/'
  const head = glob.slice(0, at)
  return head.slice(0, head.lastIndexOf('/')) || '/'
}

/** `//` and `/./` folded; a `..` segment makes the path unusable (undefined). */
export function normalizePath(path: string): string | undefined {
  const parts = path.split('/')
  if (parts.includes('..')) return undefined
  const kept = parts.filter((p, i) => p !== '.' && (p !== '' || i === 0))
  const out = kept.join('/')
  return path.startsWith('/') ? out || '/' : out
}

/** A report path made absolute: relative ones are read against the scope root. */
export function resolveFile(file: string, root: string): string | undefined {
  return normalizePath(file.startsWith('/') ? file : `${root.replace(/\/+$/, '')}/${file}`)
}

const escapeRe = (s: string) => s.replace(/[.+^${}()|[\]\\]/g, '\\$&')

/** `**` spans folders (and `/**` matches the folder itself), `*` stays in one, `?` is one character, `{a,b}` either. */
export function globToRegExp(glob: string): RegExp {
  let re = ''
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i] as string
    if (c === '*') {
      if (glob[i + 1] === '*') {
        const slashAfter = glob[i + 2] === '/'
        const slashBefore = i > 0 && glob[i - 1] === '/'
        if (slashBefore && re.endsWith('\\/') && i + 2 === glob.length) {
          // `dir/**`: the folder itself or anything below it
          re = re.slice(0, -2) + '(?:\\/.*)?'
        } else if (slashAfter) {
          re += '(?:.*\\/)?'
          i += 1
        } else re += '.*'
        i += 1
      } else re += '[^/]*'
    } else if (c === '?') re += '[^/]'
    else if (c === '{') {
      const close = glob.indexOf('}', i)
      if (close < 0) re += '\\{'
      else {
        re += `(?:${glob.slice(i + 1, close).split(',').map(escapeRe).join('|')})`
        i = close
      }
    } else if (c === '/') re += '\\/'
    else re += escapeRe(c)
  }
  return new RegExp(`^${re}$`)
}

export const matchGlob = (path: string, glob: string): boolean => globToRegExp(glob).test(path)

/** The report's `files=` list: comma-separated, `none` and blanks dropped. */
export const reportFiles = (files: string | undefined): string[] =>
  (files ?? '').split(',').map(f => f.trim()).filter(f => f !== '' && f !== 'none' && f !== '-')

/** A brief's comma list (`scope=`, `forbid=`): blanks and `none` dropped. */
export const globList = (value: string | undefined): string[] =>
  (value ?? '').split(',').map(g => g.trim()).filter(g => g !== '' && g !== 'none')

export type ScopeResult = { inScope: string[]; outOfScope: string[]; forbidden: string[] }

/**
 * Each report file, made absolute against the scope root: in scope when a
 * scope glob matches it and no forbid glob does. A path that cannot be made
 * absolute (a `..` segment) is out of scope as written.
 */
export function scopeCheck(input: { files: readonly string[]; root: string; scope: readonly string[]; forbid: readonly string[] }): ScopeResult {
  const out: ScopeResult = { inScope: [], outOfScope: [], forbidden: [] }
  const abs = (g: string) => (g.startsWith('/') ? g : `${input.root}/${g}`)
  for (const file of input.files) {
    const path = resolveFile(file, input.root)
    if (path === undefined) out.outOfScope.push(file)
    else if (input.forbid.some(g => matchGlob(path, abs(g)))) out.forbidden.push(path)
    else if (input.scope.some(g => matchGlob(path, abs(g)))) out.inScope.push(path)
    else out.outOfScope.push(path)
  }
  return out
}

export type GateOutcome = { label: string; exitCode?: number; error?: string }

export type NoRepoInput = {
  root: string
  /** The report's files, absolute, that are in scope. */
  files: readonly string[]
  missing: readonly string[]
  outOfScope: readonly string[]
  forbidden: readonly string[]
  gates: readonly GateOutcome[]
  notRerun: readonly string[]
  noGate: boolean
}

export type NoRepoVerdict = { verdict: 'verified' | 'refuted' | 'unverified'; why?: string; lines: string[] }

const plural = (n: number, one: string) => `${n} ${one}${n === 1 ? '' : 's'}`

/**
 * The verdict and its claim lines, in the native verifier's shape
 * (`claim <name>: held|failed|unchecked — <detail>`). A failed claim refutes
 * (scope first, then missing files, then the gate); else an unchecked one
 * (a gate not re-run, none at all) leaves it unverified; else verified.
 */
export function noRepoVerdict(v: NoRepoInput): NoRepoVerdict {
  const lines: string[] = []
  const failed: string[] = []
  const unchecked: string[] = []
  if (v.outOfScope.length > 0 || v.forbidden.length > 0) {
    const why = v.outOfScope.length > 0 ? `out of scope: ${v.outOfScope.join(', ')}` : `forbidden: ${v.forbidden.join(', ')}`
    lines.push(`claim scope: failed — ${why}`)
    failed.push(why)
  } else lines.push('claim scope: held — every file in scope')
  if (v.missing.length > 0) {
    const why = `missing: ${v.missing.join(', ')}`
    lines.push(`claim files: failed — ${why}`)
    failed.push(why)
  } else lines.push(`claim files: held — ${plural(v.files.length, 'file')} under ${v.root}`)
  if (v.noGate) {
    lines.push('claim gate: unchecked — no gate= in the brief')
    unchecked.push('no gate= in the brief')
  }
  for (const g of v.gates) {
    if (g.error !== undefined) {
      const why = `gate ${g.label} did not run: ${g.error}`
      lines.push(`claim gate: unchecked — ${why}`)
      unchecked.push(why)
    } else if (g.exitCode === 0) lines.push(`claim gate: held — ${g.label} exited 0`)
    else {
      const why = `gate ${g.label} exited ${g.exitCode}`
      lines.push(`claim gate: failed — ${why}`)
      failed.push(why)
    }
  }
  for (const id of v.notRerun) {
    lines.push(`claim gate: unchecked — gate not re-run: ${id}`)
    unchecked.push(`gate not re-run: ${id}`)
  }
  if (failed.length > 0) return { verdict: 'refuted', why: failed[0] as string, lines }
  if (unchecked.length > 0) return { verdict: 'unverified', why: unchecked[0] as string, lines }
  return { verdict: 'verified', lines }
}

/** `verified (no repo)`, `refuted (no repo): <why>`, `unverified (no repo): <why>`. */
export const noRepoVerdictText = (v: { verdict: string; why?: string }): string =>
  `${v.verdict} (no repo)${v.why ? `: ${v.why}` : ''}`

